          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {(cart || []).map((cItem: any, idx: number) => (
            <div key={idx} className="flex justify-between items-center text-sm">
