import { restaurantApi } from '@/lib/zodiosClients';
import { Order, OrderStatus } from '@/types';
import { getFriendlyStatusMessage } from '@features/customer-orders/model/statusMessaging';
import { RestaurantOrderDetailsModal } from '@features/restaurant-orders/components/RestaurantOrderDetailsModal';
import { Calendar, ChevronLeft, ChevronRight, DollarSign, Package, Receipt } from 'lucide-react';
import React, { useState } from 'react';

export function OrderHistory({ restaurantId, onOpenChat }: { restaurantId: string, onOpenChat?: (orderId: string) => void }) {
  const [dateFilter, setDateFilter] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const [orders, setOrders] = useState<Order[]>([]);
  const [totalPages, setTotalPages] = useState(1);
  const [totalElements, setTotalElements] = useState(0);
  const [selectedOrderForDetails, setSelectedOrderForDetails] = useState<Order | null>(null);


  React.useEffect(() => {
    if (!restaurantId) return;
    const fetchHistory = async () => {
      try {
        const queries: Record<string, string | number> = {
          page: currentPage - 1,
          size: itemsPerPage
        };
        if (dateFilter) queries.date = dateFilter;

        const res = await restaurantApi.fulfillment.get('/api/v1/restaurants/:restaurantId/fulfillment/orders/history', { params: { restaurantId }, queries });
        if (res.data) {


interface RawOrder {
  id?: string;
  orderId?: string;
  status?: string;
  items?: unknown[];
  itemsJson?: string;
  total?: number;
  totalAmount?: number;
  subtotal?: number;
  customerName?: string;
  createdAt?: string;
  estimatedCompletionTime?: string;
  updatedAt?: string;
  deliveryStatus?: string;
  sgst?: number;
  cgst?: number;
}

          // @ts-expect-error auto-migration type suppression
          const mapped = (res.data.content || []).map((o: RawOrder) => {
            let s = (o.status || '').toUpperCase();
            if (s === OrderStatus.READY_FOR_PICKUP || s === 'READY') s = OrderStatus.READY_FOR_PICKUP; 
            if (s === OrderStatus.CANCELLED_BY_RESTAURANT) s = OrderStatus.CANCELLED;

            let parsedItems = o.items || [];
            if (o.itemsJson) {
                // malformed itemsJson falls back to o.items rather than failing the row
                try { parsedItems = JSON.parse(o.itemsJson); } catch { /* keep fallback */ }
            }
            const calculatedTotal = parsedItems.reduce((acc: number, it: unknown) => {
              const item = it as { item?: { price?: number }; price?: number; quantity?: number };
              return acc + (item.item?.price || item.price || 0) * (item.quantity || 1);
            }, 0);

            return {
              ...o, 
              id: o.orderId || o.id, 
              status: s, 
              items: parsedItems,
              total: o.total || o.totalAmount || calculatedTotal,
              subtotal: o.subtotal || calculatedTotal,
              customerName: o.customerName || 'Customer',
              timestamp: o.createdAt || new Date().toISOString()
            };
          });
          setOrders(mapped as Order[]);
          setTotalPages(res.data.totalPages || 1);
          setTotalElements(res.data.totalElements || mapped.length);
        }
      } catch (err: unknown) {
        console.error('Failed to fetch history orders', err);
      }
    };
    fetchHistory();
  }, [restaurantId, dateFilter, currentPage]);

  const paginatedOrders = orders;



  return (
    <div className="bg-white/20 dark:bg-slate-900/20 backdrop-blur-md border border-rose-500/20 dark:border-rose-500/30 p-5 sm:p-8 rounded-[2rem] shadow-sm">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h4 className="font-extrabold text-lg tracking-tight uppercase font-sans text-slate-800 dark:text-[#f0ede6] flex items-center gap-2">
            <Package className="w-5 h-5 text-emerald-500" />
            Order History
          </h4>
          <p className="text-xs text-slate-500 dark:text-slate-300 mt-1">View and filter past orders. Limited to 100 per page.</p>
        </div>

        <div className="flex items-center gap-3">
          <div className="relative">
            <Calendar className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-300" />
            <input
              type="date"
              value={dateFilter}
              onChange={(e) => {
                setDateFilter(e.target.value);
                setCurrentPage(1);
              }}
              className="pl-9 pr-4 py-2 bg-white/20 dark:bg-slate-950/20 backdrop-blur-md border border-rose-500/20 dark:border-rose-500/30 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/50 outline-none w-full sm:w-auto"
            />
          </div>
          {dateFilter && (
            <button
              onClick={() => {
                setDateFilter('');
                setCurrentPage(1);
              }}
              className="text-xs text-rose-500 hover:text-rose-600 font-bold px-2"
            >
              Clear
            </button>
          )}
        </div>
      </div>

      <div className="bg-white/20 dark:bg-slate-950/20 rounded-2xl border border-rose-500/20 dark:border-rose-500/30 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-rose-500/20 dark:border-rose-500/30 bg-slate-50/50 dark:bg-slate-900/20 text-[10px] uppercase font-extrabold text-slate-500 dark:text-slate-300 tracking-wider">
                <th className="p-4 pl-6 whitespace-nowrap">Order ID</th>
                <th className="p-4 whitespace-nowrap">Date & Time</th>
                <th className="p-4 whitespace-nowrap">ETA</th>
                <th className="p-4 whitespace-nowrap">Customer</th>
                <th className="p-4 whitespace-nowrap">Items</th>
                <th className="p-4 whitespace-nowrap">Total</th>
                <th className="p-4 pr-6 whitespace-nowrap">Status</th>
                <th className="p-4 whitespace-nowrap">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50 text-sm">
              {paginatedOrders.length > 0 ? (
                paginatedOrders.map(order => (
                  <tr key={order.id} className="hover:bg-slate-50 dark:hover:bg-slate-900/20 transition-colors">
                    <td className="p-4 pl-6 font-mono text-xs text-slate-600 dark:text-[#f0ede6]">
                      {order.id.slice(0, 8)}...
                    </td>
                    <td className="p-4 whitespace-nowrap">
                      <div className="flex flex-col">
                        <span className="font-medium text-slate-800 dark:text-[#f0ede6]">
                          {new Date((order as {timestamp?: string}).timestamp || order.createdAt).toLocaleDateString()}
                        </span>
                        <span className="text-xs text-slate-500 dark:text-slate-300 font-mono">
                          {new Date((order as {timestamp?: string}).timestamp || order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                      </div>
                    </td>
                    <td className="p-4 whitespace-nowrap">
                      {order.estimatedCompletionTime ? (
                        <div className="flex flex-col">
                          <span className="font-bold text-indigo-600 dark:text-indigo-400">
                            {new Date(order.estimatedCompletionTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </span>
                        </div>
                      ) : (
                        <span className="text-slate-400 text-xs">-</span>
                      )}
                    </td>
                    <td className="p-4 whitespace-nowrap">
                      <span className="font-medium text-slate-800 dark:text-[#f0ede6]">{order.customerName}</span>
                    </td>
                    <td className="p-4">
                      <div className="flex flex-col gap-1">
                        // @ts-expect-error auto-migration type suppression
                        {order.items.map((it: unknown, idx: number) => {
                          const item = it as { quantity?: number, item?: { name?: string }, name?: string };
                          return (
                          <div key={idx} className="text-xs flex items-center gap-1.5 text-slate-600 dark:text-[#f0ede6]">
                            <span className="font-bold text-slate-800 dark:text-[#f0ede6]">{item.quantity || 1}x</span>
                            <span className="truncate max-w-[120px] sm:max-w-[180px]">{item.item?.name || (item).name || 'Item'}</span>
                          </div>
                          )
                        })}
                      </div>
                    </td>
                    <td className="p-4 whitespace-nowrap">
                      <div className="flex flex-col">
                        <div className="flex items-center gap-1 font-black text-slate-800 dark:text-[#f0ede6]">
                          <DollarSign className="w-3 h-3 text-emerald-500" />
                          {order.total?.toFixed(2)}
                        </div>
                        {(order.sgst !== undefined || order.cgst !== undefined) && (
                          <div className="text-[10px] text-slate-500 dark:text-slate-400 mt-0.5">
                            Incl. Tax: ${((order.sgst || 0) + (order.cgst || 0)).toFixed(2)}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="p-4 pr-6 whitespace-nowrap">
                      <span className={`px-2.5 py-1 rounded-md text-[10px] font-bold tracking-wider bg-rose-50 dark:bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-200/60 dark:border-rose-500/30 shadow-[0_0_12px_rgba(244,63,94,0.4)] dark:shadow-[0_0_12px_rgba(244,63,94,0.5)] uppercase`}>
                        {getFriendlyStatusMessage(order.status, order.deliveryStatus)}
                      </span>
                    </td>
                    <td className="p-4 whitespace-nowrap">
                      <div className="flex flex-col gap-2">
                        {/* Refund button removed as Restaurants do not have API permissions to issue refunds directly */}

                        {/* Restaurant's OrderHistory gives a 4 hour window from HANDED_OVER to account for delivery time */}
                        // eslint-disable-next-line react-hooks/purity
                        // eslint-disable-next-line react-hooks/purity
                        {onOpenChat && order.updatedAt && (Date.now() - new Date(order.updatedAt).getTime() < 4 * 60 * 60 * 1000) && (
                          <button
                            onClick={() => onOpenChat(order.id)}
                            className="text-xs font-bold text-blue-500 hover:text-blue-600 underline text-left"
                          >
                            Chat
                          </button>
                        )}
                        <button
                          onClick={() => setSelectedOrderForDetails(order)}
                          className="flex items-center gap-1 text-xs font-bold text-emerald-500 hover:text-emerald-600 text-left"
                        >
                          <Receipt className="w-3 h-3" />
                          Details
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={8} className="p-16 text-center">
                    <div className="flex flex-col items-center justify-center gap-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
                      <div className="relative">
                        <div className="absolute inset-0 bg-rose-500/20 dark:bg-rose-500/10 rounded-full blur-xl animate-pulse"></div>
                        <div className="w-20 h-20 bg-white dark:bg-slate-800 rounded-full flex items-center justify-center shadow-lg border border-slate-100 dark:border-slate-700 relative z-10">
                          <Package className="w-10 h-10 text-rose-400 dark:text-rose-500" strokeWidth={1.5} />
                        </div>
                      </div>
                      <h3 className="text-lg font-bold text-slate-800 dark:text-[#f0ede6]">No Orders Found</h3>
                      <p className="text-sm text-slate-500 dark:text-slate-400 max-w-sm">
                        {dateFilter 
                          ? "We couldn't find any orders for the selected date. Try choosing a different date or clear the filter." 
                          : "You don't have any past orders yet. Once you start receiving orders, they will appear here."}
                      </p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {totalPages > 1 && (
        <div className="mt-6 flex flex-wrap items-center justify-between gap-4">
          <div className="text-xs text-slate-500 dark:text-slate-300 font-medium">
            Showing <span className="font-bold text-slate-800 dark:text-[#f0ede6]">{(currentPage - 1) * itemsPerPage + 1}</span> to <span className="font-bold text-slate-800 dark:text-[#f0ede6]">{Math.min(currentPage * itemsPerPage, totalElements)}</span> of <span className="font-bold text-slate-800 dark:text-[#f0ede6]">{totalElements}</span> orders
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className="p-2 rounded-lg bg-white/20 dark:bg-slate-950/20 backdrop-blur-md border border-rose-500/20 dark:border-rose-500/30 text-slate-600 dark:text-[#f0ede6] disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors hover:shadow-[0_0_12px_rgba(244,63,94,0.4)] dark:hover:shadow-[0_0_12px_rgba(244,63,94,0.5)] hover:border-rose-500/50 transition-all"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>

            <div className="flex items-center gap-1">
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                let pageNum = currentPage;
                if (totalPages <= 5) pageNum = i + 1;
                else if (currentPage <= 3) pageNum = i + 1;
                else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                else pageNum = currentPage - 2 + i;

                return (
                  <button
                    key={pageNum}
                    onClick={() => setCurrentPage(pageNum)}
                    className={`w-8 h-8 rounded-lg text-xs font-bold transition-colors ${
                      currentPage === pageNum
                        ? 'bg-emerald-500 text-white'
                        : 'bg-white/20 dark:bg-slate-950/20 backdrop-blur-md border border-rose-500/20 dark:border-rose-500/30 text-slate-600 dark:text-[#f0ede6] hover:bg-slate-50 dark:hover:bg-slate-900'
                    }`}
                  >
                    {pageNum}
                  </button>
                );
              })}
            </div>

            <button
              onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
              disabled={currentPage === totalPages}
              className="p-2 rounded-lg bg-white/20 dark:bg-slate-950/20 backdrop-blur-md border border-rose-500/20 dark:border-rose-500/30 text-slate-600 dark:text-[#f0ede6] disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors hover:shadow-[0_0_12px_rgba(244,63,94,0.4)] dark:hover:shadow-[0_0_12px_rgba(244,63,94,0.5)] hover:border-rose-500/50 transition-all"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      <RestaurantOrderDetailsModal
        order={selectedOrderForDetails}
        isOpen={!!selectedOrderForDetails}
        onClose={() => setSelectedOrderForDetails(null)}
      />
    </div>
  );
}

import { Order, OrderStatus } from '@/types';
import { RestaurantOrderDetailsModal } from '@features/restaurant-orders/components/RestaurantOrderDetailsModal';
import { Badge, Button, FormField, Input } from '@shared/ui';
import { AnimatePresence, motion } from 'framer-motion';
import {
    Bike,
    Check,
    CheckCircle2,
    Clock,
    Flame,
    KeyRound,
    MapPin,
    MessageSquare,
    Receipt,
    RefreshCw,
    Send,
    User,
    XCircle
} from 'lucide-react';
import React, { useState } from 'react';

// Utility
const getFriendlyDeliveryStatusMessage = (status: string | undefined): string => {
  if (!status) return "Searching...";
  switch (status.toUpperCase()) {
    case 'PENDING': return 'Searching...';
    case 'ASSIGNED': return 'On the way';
    case 'ARRIVED_AT_RESTAURANT': return 'At restaurant';
    case 'PICKED_UP': return 'Out for delivery';
    case 'ARRIVED_AT_CUSTOMER': return 'Arrived at customer';
    case 'DELIVERED': return 'Delivered';
    case 'CANCELLED': return 'Cancelled';
    default: return status;
  }
};

interface RestaurantOrderCardProps {
  order: Order;
  cardDelayStatus?: Record<string, { minutes: number, reason: string }>;

  // Status check for styling
  isNewPlaced?: boolean;
  isRequestedDelay?: boolean;
  isCooking?: boolean;
  isPrepared?: boolean;
  isBeingDelivered?: boolean;

  // Actions
  handleStatusTransition: (order: Order) => void;
  setSelectedChatOrder: (order: Order) => void;

  // Handlers for the form submissions
  handleCardCancelSubmit: (orderId: string, reason: string) => void;
  handleCardDelaySubmit: (orderId: string, minutes: string, reason: string) => void;
  handleCardPartialRefundSubmit: (orderId: string, amount: string, reason: string) => void;
}

export const RestaurantOrderCard: React.FC<RestaurantOrderCardProps> = ({
  order,
  cardDelayStatus = {},
  isNewPlaced,
  isRequestedDelay,
  isCooking,
  isPrepared,
  isBeingDelivered,
  handleStatusTransition,
  setSelectedChatOrder,
  handleCardCancelSubmit,
  handleCardDelaySubmit,
  handleCardPartialRefundSubmit
}) => {
  // Local state for modals to avoid global record bloat in parent
  const [activeModal, setActiveModal] = useState<'none' | 'cancel' | 'delay' | 'refund'>('none');
  const [showDetails, setShowDetails] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOtp, setShowOtp] = useState(false);

  React.useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setIsSubmitting(false);
  }, [order.status]);


  // Form fields
  const [cancelReason, setCancelReason] = useState('');
  const [delayMinutes, setDelayMinutes] = useState('10');
  const [delayReason, setDelayReason] = useState('');
  const [refundAmount, setRefundAmount] = useState('');
  const [refundReason, setRefundReason] = useState('');

  const submitCancel = () => {
    handleCardCancelSubmit(order.id, cancelReason);
    setActiveModal('none');
    setCancelReason('');
  };

  const submitDelay = () => {
    handleCardDelaySubmit(order.id, delayMinutes, delayReason);
    setActiveModal('none');
    setDelayReason('');
  };

  const submitRefund = () => {
    handleCardPartialRefundSubmit(order.id, refundAmount, refundReason);
    setActiveModal('none');
    setRefundAmount('');
    setRefundReason('');
  };

  const statusStyling = () => {
    if (order.status === OrderStatus.AWAITING_DELAY_APPROVAL) {
      return { ring: 'ring-red-500/20 border-red-500/30', bg: 'bg-red-500/[0.01]' };
    }
    if (order.status === OrderStatus.PREPARING) {
      return { ring: 'ring-orange-500/20 border-orange-500/30', bg: 'bg-orange-500/[0.01]' };
    }
    return { ring: 'ring-amber-500/10', bg: 'border-rose-500/20 dark:border-rose-500/30' };
  };
  const styles = statusStyling();

  return (
    <motion.div 
      layoutId={`card-₹{order.id}`}
      className={`glass-card p-4 space-y-3.5 relative overflow-hidden transition-all ${styles.bg} ${styles.ring}`}
    >
      <div className="flex justify-between items-start">
        <div>
          <span className="text-xs font-mono font-bold text-orange-500">#{order.id.substring(0, 8)}</span>
          <span className="text-[10px] text-slate-400 dark:text-slate-300 font-medium block">{order.timestamp}</span>
        </div>
        <Badge 
          variant={order.status === OrderStatus.AWAITING_DELAY_APPROVAL ? 'danger' : 'primary'} 
          icon={order.status === OrderStatus.PREPARING ? <Flame className="w-3 h-3 text-orange-500 animate-bounce" /> : undefined}
          pulse={order.status === OrderStatus.AWAITING_DELAY_APPROVAL}
          className="shadow-[0_0_12px_rgba(244,63,94,0.4)] dark:shadow-[0_0_12px_rgba(244,63,94,0.5)]"
        >
          {order.status === OrderStatus.AWAITING_DELAY_APPROVAL ? 'ON HOLD' : 
            order.status === OrderStatus.PREPARING ? 'COOKING' :
            order.status === OrderStatus.ACCEPTED ? 'ACCEPTED' :
            order.status === OrderStatus.READY_FOR_PICKUP ? 'READY' :
            order.status === OrderStatus.HANDED_OVER ? 'DISPATCHED' :
            'PLACED'}
        </Badge>
      </div>

      <div className="bg-slate-50 dark:bg-slate-950/40 rounded-xl border border-rose-500/20 dark:border-rose-500/30 overflow-hidden divide-y divide-rose-500/10 dark:divide-rose-500/20">
        <div className="p-2.5 space-y-1 text-[11px]">
          <div className="flex items-center justify-between gap-1">
            <p className="font-bold text-slate-700 dark:text-[#f0ede6] flex items-center gap-1">
              <User className="w-3 h-3 text-slate-400 dark:text-slate-300" />
              <span className="truncate max-w-[120px]">{order.customerName}</span>
            </p>
            {order.estimatedCompletionTime && (
              <span className="flex items-center gap-1 text-[9px] text-amber-500 font-bold shrink-0">
                <Clock className="w-2.5 h-2.5" />
                {new Date(order.estimatedCompletionTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            )}
          </div>
          {order.deliveryAddress && (
            <div className="flex items-center gap-1 text-[10px] text-slate-400 dark:text-slate-300">
              <MapPin className="w-3 h-3 text-rose-450 shrink-0" />
              <span className="truncate max-w-[170px]">{order.deliveryAddress}</span>
            </div>
          )}
        </div>

        <div className="p-2.5 bg-indigo-50/30 dark:bg-indigo-950/20">
          <div className="flex items-center justify-between text-[10px] text-slate-400 dark:text-slate-300 mb-1.5">
            <span className="font-semibold text-[9px] uppercase tracking-wider text-indigo-400/80">Courier</span>
            <span className="font-bold flex items-center gap-1 text-indigo-400 text-[9px] uppercase">
              <span className="w-1 h-1 rounded-full bg-indigo-500 animate-ping" />
              {getFriendlyDeliveryStatusMessage(order.deliveryStatus)}
            </span>
          </div>
          {order.riderName ? (
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 rounded-full bg-indigo-500/15 flex items-center justify-center text-indigo-550 shrink-0">
                <Bike className="w-3 h-3" />
              </div>
              <p className="font-bold text-[11px] text-slate-750 dark:text-[#f0ede6] truncate">{order.riderName}</p>
            </div>
          ) : (
            <div className="flex items-center gap-2 py-0.5 text-slate-450">
              <RefreshCw className="w-3 h-3 text-slate-400 dark:text-slate-300 animate-spin shrink-0" />
              <span className="text-[9px]">Awaiting assignment...</span>
            </div>
          )}
        </div>
      </div>

      <div className="space-y-1">
        <span className="text-[9px] text-slate-400 dark:text-slate-300 font-extrabold uppercase font-mono">Dishes ({order.items.length})</span>
        <div className="space-y-1 max-h-[100px] overflow-y-auto scrollbar-thin pl-1">
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {order.items.map((cartItem: any, idx: number) => (
            <div key={cartItem.item?.id || idx} className="flex justify-between text-[11px]">
              <span className="text-slate-600 dark:text-[#f0ede6] font-medium">
                <span className="font-mono text-orange-500 font-bold pr-1">{cartItem.quantity || 1}x</span> {cartItem.item?.name || cartItem.name || 'Item'}
              </span>
              <span className="text-slate-400 dark:text-slate-300 font-mono">₹{((cartItem.item?.price || cartItem.price || 0) * (cartItem.quantity || 1)).toFixed(2)}</span>
            </div>
          ))}
        </div>
      </div>

      {cardDelayStatus[order.id] && (
        <div className="bg-amber-500/10 dark:bg-amber-500/5 text-amber-600 dark:text-amber-400 text-[10px] font-bold p-2 rounded-xl border border-amber-500/15 flex items-center gap-1.5 animate-pulse">
          <Clock className="w-3.5 h-3.5 shrink-0" />
          <span>Revised ETA (+{cardDelayStatus[order.id].minutes} min) logged with API</span>
        </div>
      )}

    <div className="pt-2.5 border-t border-rose-500/20 dark:border-rose-500/30 flex flex-col gap-2">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <span className="text-[9px] text-slate-400 dark:text-slate-300 uppercase font-mono block">Order Value</span>
            <span className="text-xs font-bold text-slate-850 dark:text-[#f0ede6] font-mono">₹{order.total?.toFixed(2) || '0.00'}</span>
          </div>
          {order.foodCost !== undefined && (
            <div className="space-y-1">
              <span className="text-[9px] text-slate-400 dark:text-slate-300 uppercase font-mono block">Food Cost</span>
              <span className="text-xs font-bold text-slate-850 dark:text-[#f0ede6] font-mono">₹{order.foodCost.toFixed(2)}</span>
            </div>
          )}
          {order.restaurantPlatformFee !== undefined && order.restaurantPlatformFee > 0 && (
            <div className="space-y-1">
              <span className="text-[9px] text-slate-400 dark:text-slate-300 uppercase font-mono block">Platform Fee</span>
              <span className="text-xs font-bold text-rose-500 font-mono">-₹{order.restaurantPlatformFee.toFixed(2)}</span>
            </div>
          )}
          <div className="space-y-1">
            <span className="text-[9px] text-slate-400 dark:text-slate-300 uppercase font-mono block">Your Payout</span>
            <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 font-mono">
              ₹{order.restaurantPayout !== undefined ? order.restaurantPayout.toFixed(2) : (order.total || 0).toFixed(2)}
            </span>
          </div>

          <div className="flex gap-2">
            {isNewPlaced && (
               <Button
                 variant="secondary"
                 size="sm"
                 icon={<Clock className="w-3.5 h-3.5" />}
                 onClick={() => setActiveModal(activeModal === 'delay' ? 'none' : 'delay')}
               />
            )}


            <Button
              variant="secondary"
              size="sm"
              icon={<MessageSquare className="w-3 h-3 text-blue-500" />}
              onClick={() => setSelectedChatOrder(order)}
            />

            <Button
              variant="secondary"
              size="sm"
              icon={<Receipt className="w-3.5 h-3.5 text-emerald-500" />}
              onClick={() => setShowDetails(true)}
            />
          </div>
        </div>

        <div className="flex gap-1.5 pt-1.5">
            {!isBeingDelivered && (
              <Button
                variant="danger"
                size="sm"
                className="flex-1 shadow-none bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 border-red-500/20"
                icon={<XCircle className="w-3.5 h-3.5" />}
                onClick={() => setActiveModal(activeModal === 'cancel' ? 'none' : 'cancel')}
              >
                Cancel
              </Button>
            )}

            {isNewPlaced && (
              <Button
                variant="warning"
                size="sm"
                className="flex-[2] shadow-sm"
                disabled={isSubmitting}
                icon={isSubmitting ? <RefreshCw className="w-3.5 h-3.5 shrink-0 animate-spin" /> : <Check className="w-3.5 h-3.5 shrink-0" />}
                onClick={() => {
                  setIsSubmitting(true);
                  handleStatusTransition(order);
                }}
              >
                {isSubmitting ? 'Accepting...' : 'Accept Order'}
              </Button>
            )}

            {(isCooking || isRequestedDelay) && (
              <>
                {order.status === OrderStatus.ACCEPTED ? (
                  <Button
                    variant="warning"
                    size="sm"
                    className="flex-[2] shadow-sm"
                    disabled={isSubmitting}
                    icon={isSubmitting ? <RefreshCw className="w-3.5 h-3.5 shrink-0 animate-spin" /> : undefined}
                    onClick={() => {
                      setIsSubmitting(true);
                      handleStatusTransition(order);
                    }}
                  >
                    {isSubmitting ? 'Starting...' : 'Start Cook'}
                  </Button>
                ) : (
                  <Button
                    variant="success"
                    size="sm"
                    className="flex-[2] shadow-sm bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-700 dark:text-emerald-300 border-emerald-500/30"
                    disabled={isSubmitting}
                    icon={isSubmitting ? <RefreshCw className="w-3.5 h-3.5 shrink-0 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />}
                    onClick={() => {
                      setIsSubmitting(true);
                      handleStatusTransition(order);
                    }}
                  >
                    {isSubmitting ? 'Marking...' : 'Mark Prepared'}
                  </Button>
                )}
              </>
            )}

            {(isPrepared || isBeingDelivered) && (
              <Button
                variant="primary"
                size="sm"
                className="flex-[2] shadow-sm"
                icon={!showOtp ? <KeyRound className="w-3.5 h-3.5" /> : undefined}
                onClick={() => {
                  setShowOtp(true);
                  setTimeout(() => setShowOtp(false), 6000);
                }}
              >
                {showOtp ? (
                  <span className="font-mono tracking-widest text-base">
                    {order.pickupOtp || 'N/A'}
                  </span>
                ) : (
                  'Show Handover OTP'
                )}
              </Button>
            )}
        </div>

        {/* Drawers */}
        {activeModal === 'cancel' && (
          <div className="mt-2 p-3 bg-red-50 dark:bg-red-950/20 rounded-xl border border-red-200 dark:border-red-900/50 space-y-2 animate-in slide-in-from-top-2 duration-200">
            <FormField label="Reason for cancellation">
              <Input 
                type="text" 
                placeholder="e.g. Out of stock, Kitchen busy..."
                value={cancelReason}
                onChange={(e) => setCancelReason(e.target.value)}
              />
            </FormField>
            <div className="flex gap-2 pt-1">
              <Button variant="secondary" size="sm" className="flex-1" onClick={() => setActiveModal('none')}>
                Back
              </Button>
              <Button variant="danger" size="sm" className="flex-1" onClick={submitCancel}>
                Confirm Cancel
              </Button>
            </div>
          </div>
        )}

        {activeModal === 'refund' && (
          <div className="mt-2 p-3 bg-blue-50 dark:bg-blue-950/20 rounded-xl border border-blue-200 dark:border-blue-900/50 space-y-2 animate-in slide-in-from-top-2 duration-200">
            <FormField label="Refund Amount (₹)">
              <Input 
                type="number" 
                placeholder="0.00"
                step="0.01"
                min="0.01"
                value={refundAmount}
                onChange={(e) => setRefundAmount(e.target.value)}
              />
            </FormField>
            <FormField label="Reason for partial refund">
              <Input 
                type="text" 
                placeholder="e.g. Missing Item..."
                value={refundReason}
                onChange={(e) => setRefundReason(e.target.value)}
              />
            </FormField>
            <div className="flex gap-2 pt-1">
              <Button variant="secondary" size="sm" className="flex-1" onClick={() => setActiveModal('none')}>
                Back
              </Button>
              <Button variant="primary" size="sm" className="flex-1" onClick={submitRefund}>
                Issue Refund
              </Button>
            </div>
          </div>
        )}

        <AnimatePresence>
          {activeModal === 'delay' && (
            <motion.div 
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="overflow-hidden border-t border-rose-500/20 dark:border-rose-500/30 pt-2.5 mt-1 space-y-2.5"
            >
              <div className="space-y-1">
                <label className="text-[9px] font-bold font-mono text-slate-400 dark:text-slate-300 uppercase">Delay Duration</label>
                <div className="grid grid-cols-4 gap-1">
                  {['5', '10', '15', '20'].map(m => (
                    <button
                      key={m}
                      type="button"
                      onClick={() => setDelayMinutes(m)}
                      className={`py-1 text-[10px] font-mono font-bold rounded-lg border cursor-pointer transition-all ${
                        delayMinutes === m
                          ? 'bg-amber-500 border-transparent text-white'
                          : 'bg-slate-50 dark:bg-slate-955 border-rose-500/20 dark:border-rose-500/30 text-slate-400 dark:text-slate-300'
                      }`}
                    >
                      +{m} Min
                    </button>
                  ))}
                </div>
              </div>

              <FormField label="Reason for delay">
                <Input 
                  type="text"
                  value={delayReason}
                  onChange={(e) => setDelayReason(e.target.value)}
                  placeholder="e.g. High custom baking orders"
                />
              </FormField>

              <Button
                variant="primary"
                size="sm"
                className="w-full mt-2"
                icon={<Send className="w-3 h-3 text-rose-450" />}
                onClick={submitDelay}
              >
                Submit Delay
              </Button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <RestaurantOrderDetailsModal
        order={order}
        isOpen={showDetails}
        onClose={() => setShowDetails(false)}
      />
    </motion.div>
  );
};

import { restaurantApi } from '@/lib/zodiosClients';
import { Order } from '@/types';
import { Button } from '@shared/ui';
import { AnimatePresence, motion } from 'framer-motion';
import { CheckCircle2, Receipt, X } from 'lucide-react';
import React, { useEffect, useState } from 'react';

interface RestaurantOrderDetailsModalProps {
  order: Order | null;
  isOpen: boolean;
  onClose: () => void;
}

export const RestaurantOrderDetailsModal: React.FC<RestaurantOrderDetailsModalProps> = ({ order, isOpen, onClose }) => {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [invoice, setInvoice] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen && order) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setLoading(true);
      setError(null);
      // Fetch transparent invoice details
      restaurantApi.fulfillment.get('/api/v1/restaurants/:restaurantId/fulfillment/orders/:orderId/invoice', { params: { restaurantId: order.restaurantId, orderId: order.id } })
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .then((res: any) => {
          setInvoice(res);
        })
        .catch((err) => {
          console.error("Failed to load invoice:", err);
          setError("Could not load full invoice details. Displaying available data.");
        })
        .finally(() => {
          setLoading(false);
        });
    } else {
      setInvoice(null);
    }
  }, [isOpen, order]);

  if (!isOpen || !order) return null;

  const data = invoice || order;

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
          className="bg-white dark:bg-slate-900 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800 flex flex-col max-h-[90vh]"
        >
          {/* Header */}
          <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl z-10">
            <div>
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
                <Receipt className="w-6 h-6 text-emerald-500" />
                Order Details
              </h2>
              <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
                Order #{order.id.slice(0, 8).toUpperCase()}
              </p>
            </div>
            <button
              onClick={onClose}
              className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Content */}
          <div className="p-6 overflow-y-auto custom-scrollbar">
            {loading ? (
              <div className="flex flex-col items-center justify-center py-12">
                <div className="w-8 h-8 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" />
                <p className="mt-4 text-slate-500 dark:text-slate-400 font-medium">Loading precise invoice data...</p>
              </div>
            ) : (
              <div className="space-y-8">
                {error && (
                  <div className="p-4 bg-amber-500/10 border border-amber-500/20 rounded-2xl">
                    <p className="text-sm text-amber-600 dark:text-amber-400 font-medium">{error}</p>
                  </div>
                )}

                {/* Customer Info */}
                <div>
                  <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4">Customer Details</h3>
                  <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-4 border border-slate-100 dark:border-slate-800">
                    <p className="font-medium text-slate-900 dark:text-white">{data.customerName || 'Customer'}</p>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">{data.deliveryAddress}</p>
                  </div>
                </div>

                {/* Items */}
                <div>
                  <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4">Order Items</h3>
                  <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-4 border border-slate-100 dark:border-slate-800 space-y-3">
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    {data.items?.map((item: any, i: number) => (
                      <div key={i} className="flex justify-between items-center">
                        <div className="flex items-center gap-3">
                          <span className="w-6 h-6 rounded-md bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-xs font-semibold text-slate-600 dark:text-slate-300">
                            {item.quantity}x
                          </span>
                          <span className="text-slate-700 dark:text-slate-200 font-medium">{item.name}</span>
                        </div>
                        <span className="text-slate-900 dark:text-white font-medium">
                          ₹{(item.price * item.quantity).toFixed(2)}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Transparent Financial Breakdown */}
                <div>
                  <h3 className="text-sm font-semibold text-emerald-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                    <CheckCircle2 className="w-4 h-4" />
                    Transparent Financial Breakdown
                  </h3>
                  <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-5 border border-slate-100 dark:border-slate-800 space-y-4">

                    {/* The Customer's Perspective */}
                    <div>
                      <h4 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2">Customer Paid</h4>
                      <div className="space-y-2 text-sm pl-2 border-l-2 border-slate-200 dark:border-slate-700">
                        <div className="flex justify-between text-slate-600 dark:text-slate-300">
                          <span>Item Total (Food Cost)</span>
                          <span>₹{(data.itemTotal || data.foodCost || 0).toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600 dark:text-slate-300">
                          <span>SGST <span className="text-xs text-slate-400">(Collected & paid by Platform)</span></span>
                          <span>₹{(data.sgst || 0).toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600 dark:text-slate-300">
                          <span>CGST <span className="text-xs text-slate-400">(Collected & paid by Platform)</span></span>
                          <span>₹{(data.cgst || 0).toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600 dark:text-slate-300">
                          <span>Delivery Fee (Customer)</span>
                          <span>₹{(data.deliveryFee || 0).toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600 dark:text-slate-300">
                          <span>Platform Fee (Customer)</span>
                          <span>₹{(data.customerPlatformFee || 0).toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between font-semibold text-slate-800 dark:text-slate-200 pt-2">
                          <span>Total Paid by Customer</span>
                          <span>₹{(data.totalAmount || data.total || 0).toFixed(2)}</span>
                        </div>
                      </div>
                    </div>

                    <div className="h-px bg-slate-200 dark:bg-slate-700 w-full" />

                    {/* The Restaurant's Perspective */}
                    <div>
                      <h4 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2">Restaurant Revenue & Deductions</h4>
                      <div className="space-y-2 text-sm pl-2 border-l-2 border-slate-200 dark:border-slate-700">
                        <div className="flex justify-between text-slate-600 dark:text-slate-300">
                          <span>Food Value (Item Total)</span>
                          <span>₹{(data.itemTotal || data.foodCost || 0).toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-rose-500 dark:text-rose-400">
                          <span>Platform Fee (Restaurant)</span>
                          <span>- ₹{(data.restaurantPlatformFee || 0).toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-rose-500 dark:text-rose-400">
                          <span>Delivery Contribution</span>
                          <span>- ₹{(data.restaurantDeliveryContribution || 0).toFixed(2)}</span>
                        </div>
                        {data.platformBonus > 0 && (
                          <div className="flex justify-between text-emerald-500 dark:text-emerald-400">
                            <span>Platform Bonus</span>
                            <span>+ ₹{(data.platformBonus || 0).toFixed(2)}</span>
                          </div>
                        )}
                        <div className="flex justify-between font-bold text-lg text-emerald-600 dark:text-emerald-400 pt-2">
                          <span>Net Restaurant Payout</span>
                          <span>₹{(data.restaurantPayout || 0).toFixed(2)}</span>
                        </div>
                      </div>
                    </div>

                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="p-4 border-t border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50">
             <Button fullWidth variant="outline" onClick={onClose}>
               Close Details
             </Button>
          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  );
};

